#include <string>
#include <sstream>

std::string convertToHtml(const std::string& inputText) {
    std::stringstream ss;
    bool inEmphasis = false;
    bool inBold = false;

    for (char c : inputText) {
        if (c == '*' && !inBold) {
            // Start of emphasis
            ss << "<em>";
            inEmphasis = true;
        } else if (c == '*' && inBold) {
            // End of bold, start of emphasis
            ss << "</strong><em>";
            inBold = false;
        } else if (c == '*' && inEmphasis) {
            // End of emphasis
            ss << "</em>";
            inEmphasis = false;
        } else if (c == '_' && !inEmphasis) {
            // Start of bold
            ss << "<strong>";
            inBold = true;
        } else if (c == '_' && inEmphasis) {
            // End of emphasis, start of bold
            ss << "</em><strong>";
            inEmphasis = false;
        } else if (c == '_' && inBold) {
            // End of bold
            ss << "</strong>";
            inBold = false;
        } else {
            // Regular character
            ss << c;
        }
    }

    if (inEmphasis) {
        ss << "</em>";
    }
    if (inBold) {
        ss << "</strong>";
    }

    return ss.str();
}
```

This function converts text in markdown-style underscores (`_`) and asterisks (`*`) for emphasis and bold, respectively, to HTML tags `<em>` and `<strong>`. 

Here's an example usage:

```cpp
#include <iostream>

int main() {
    std::string inputText = "This is *bold* and _emphasized_ text.";
    std::string htmlText = convertToHtml(inputText);

    std::cout << "Input text:\n" << inputText << "\n";
    std::cout << "HTML text:\n" << htmlText << "\n";

    return 0;
}
```

Output:

```
Input text:
This is *bold* and _emphasized_ text.

HTML text:
This is <strong>bold</strong> and <em>emphasized</em> text.
```

