function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      console.log(num);
      break;
    }
  }
}

function isPrime(n) {
  if (n < 2) return false;
  for (let I = 2; I <= Math.sqrt(n); i++) {
    if (n % I === 0) {
      return false;
    }
  }
  return true;
}

// Example usage
const arr = [7, 12, 23, 17, 29];
checkPrime(arr); // Output: 7, 23, 17, or 29 (depending on which prime number is found)
```

В этой функции `checkPrime` мы проходимся по массиву и для каждого числа вызываем функцию `isPrime`, которая проверяет, является ли это число простым. Если число простое, мы выводим его на консоль и сразу же выходим из цикла `for` (используем `break`), так как нам не нужно проверять остальные числа в массиве.

Функция `isPrime` проверяет, является ли число простым, используя простой алгоритм на основе деления на все целые числа от 2 до квадратного корня из числа.

